package com.nageoffer.ai.ragent.triage.eval;

import com.nageoffer.ai.ragent.triage.model.Fact;
import com.nageoffer.ai.ragent.triage.model.FactPolarity;
import java.util.*;

abstract class TriageRegressionJudgeSupport {
static final String U="Understanding",R="Reducer",P="Planner",H="History",D="RiskDecision",F="Final behavior",C="Compatibility";
static final Map<String,List<String>> REASK=Map.of("REASK_FEVER_PRESENCE",List.of("FEVER_PRESENCE","fever","发热"),"REASK_NAUSEA_PRESENCE",List.of("NAUSEA_PRESENCE","nausea","恶心"),"REASK_VOMITING_PRESENCE",List.of("VOMITING_PRESENCE","vomiting","呕吐"),"REASK_DURATION",List.of("DURATION","duration","持续时间"),"REASK_BODY_PART",List.of("BODY_PART","bodyPart","部位"));
public List<TriageRegressionJudgement> judge(List<TriageEvalCase> cs,List<TriageEvalObservedCaseResult> os){List<TriageRegressionJudgement> out=new ArrayList<>();if(cs==null||os==null)return out;for(int i=0;i<Math.min(cs.size(),os.size());i++)out.add(judgeCase(cs.get(i),os.get(i)));return out;}
public TriageRegressionJudgement judgeCase(TriageEvalCase c,TriageEvalObservedCaseResult o){List<String> ok=new ArrayList<>(),bad=new ArrayList<>();var n=o==null?null:o.getNormalizedResult();var e=c==null?null:c.getExpected();if(e!=null){u(e.getUnderstanding(),n==null?null:n.getUnderstanding(),ok,bad);r(e.getReducer(),n==null?null:n.getReducer(),ok,bad);p(e.getPlanner(),n==null?null:n.getPlanner(),ok,bad);h(e.getHistory(),n==null?null:n.getHistory(),n==null?null:n.getReducer(),ok,bad);d(e.getRiskDecision(),n==null?null:n.getRiskDecision(),ok,bad);fb(c,e,n,ok,bad);}forbidden(c==null?null:c.getForbidden(),n,ok,bad);var history=n==null?null:n.getHistory();var reducer=n==null?null:n.getReducer();return TriageRegressionJudgement.builder().caseId(c==null?null:c.getId()).category(c==null?null:c.getCategory()).priority(c==null?null:c.getPriority()).passed(bad.isEmpty()).passedChecks(ok).failedChecks(bad).reducerComplaintTruth(reducer==null?null:reducer.getComplaintTruth()).historyFinalPrimaryComplaint(history==null?null:history.getFinalPrimaryComplaint()).historyReducerComplaintTruth(history==null?null:history.getReducerComplaintTruth()).complaintTruthSynchronized(history==null?null:history.getComplaintTruthSynchronized()).observedResult(o).build();}
void u(TriageEvalCase.UnderstandingExpectation e,TriageEvalNormalizer.UnderstandingSnapshot a,List<String> ok,List<String> bad){if(e==null)return;eq(U,"intent",e.getIntent(),a==null?null:a.getIntent(),ok,bad);eq(U,"primaryComplaint",e.getPrimaryComplaint(),a==null?null:a.getPrimaryComplaint(),ok,bad);frag(U,"answeredSlots",e.getAnsweredSlotsContains(),a==null?List.of():a.getAnsweredSlots(),ok,bad);frag(U,"riskSignals",e.getRiskSignalsContains(),a==null?List.of():a.getRiskSignals(),ok,bad);frag(U,"corrections",e.getCorrectionsContains(),a==null?List.of():a.getCorrections(),ok,bad);}
void r(TriageEvalCase.ReducerExpectation e,TriageEvalNormalizer.ReducerSnapshot a,List<String> ok,List<String> bad){if(e==null)return;slots(R,"reducedSlotValues",e.getReducedSlotValues(),a==null?null:a.getReducedSlotValues(),ok,bad,false);frag(R,"answeredSlots",e.getAnsweredSlotsContains(),a==null?List.of():a.getAnsweredSlots(),ok,bad);nfrag(R,"pendingSlots",e.getPendingSlotsNotContains(),a==null?List.of():a.getPendingCandidates(),ok,bad);frag(R,"riskSignals",e.getRiskSignalsContains(),a==null?List.of():a.getAccumulatedRiskSignals(),ok,bad);atleast(R,"correctionCount",e.getCorrectionCountAtLeast(),a==null?null:a.getCorrectionCount(),ok,bad);}
void p(TriageEvalCase.PlannerExpectation e,TriageEvalNormalizer.PlannerSnapshot a,List<String> ok,List<String> bad){if(e==null)return;frag(P,"candidateGaps",e.getCandidateGapsContains(),a==null?List.of():a.getCandidateGaps(),ok,bad);frag(P,"selectedGaps",e.getSelectedGapsContains(),a==null?List.of():a.getSelectedGaps(),ok,bad);frag(P,"suppressedGaps",e.getSuppressedGapsContains(),a==null?List.of():a.getSuppressedGaps(),ok,bad);frag(P,"askabilityDecisions",e.getAskabilityDecisionsContains(),a==null?List.of():a.getAskabilityDecisions(),ok,bad);nfrag(P,"selectedGaps",e.getMustNotSelectGaps(),a==null?List.of():a.getSelectedGaps(),ok,bad);}
void h(TriageEvalCase.HistoryExpectation e,TriageEvalNormalizer.HistorySnapshot a,TriageEvalNormalizer.ReducerSnapshot r,List<String> ok,List<String> bad){if(e==null)return;atleast(H,"turnUnderstandingHistoryCount",e.getTurnUnderstandingCountAtLeast(),a==null?null:a.getTurnUnderstandingHistoryCount(),ok,bad);atleast(H,"stateReducerHistoryCount",e.getStateReducerHistoryCountAtLeast(),a==null?null:a.getStateReducerHistoryCount(),ok,bad);atleast(H,"riskDecisionHistoryCount",e.getRiskDecisionHistoryCountAtLeast(),a==null?null:a.getRiskDecisionHistoryCount(),ok,bad);String exp=histComplaint(e);if(exp!=null){eq(H,"finalPrimaryComplaint",exp,a==null?null:a.getFinalPrimaryComplaint(),ok,bad);eq(H,"reducerComplaintTruth",exp,a==null?null:a.getReducerComplaintTruth(),ok,bad);eq(H,"reducerComplaintTruth(observed in reducer snapshot)",exp,r==null?null:r.getComplaintTruth(),ok,bad);}if(a!=null&&a.getComplaintTruthSynchronized()!=null){if(Boolean.TRUE.equals(a.getComplaintTruthSynchronized()))ok.add(tag(H,"complaintTruthSynchronized=true"));else bad.add(tag(H,"expected complaintTruthSynchronized=true, actual=false"));}}void d(TriageEvalCase.RiskDecisionExpectation e,TriageEvalNormalizer.RiskDecisionSnapshot a,List<String> ok,List<String> bad){if(e==null)return;eq(D,"decisionType",e.getDecisionType(),a==null?null:a.getDecisionType(),ok,bad);eq(D,"shouldInterrupt",e.getShouldInterrupt(),a==null?null:a.getShouldInterrupt(),ok,bad);eq(D,"needsMoreInfo",e.getNeedsMoreInfo(),a==null?null:a.getNeedsMoreInfo(),ok,bad);frag(D,"confirmedRiskGaps",e.getConfirmedRiskGapsContains(),a==null?List.of():a.getConfirmedRiskGaps(),ok,bad);frag(D,"suspectedRiskGaps",e.getSuspectedRiskGapsContains(),a==null?List.of():a.getSuspectedRiskGaps(),ok,bad);frag(D,"unresolvedRiskGaps",e.getUnresolvedRiskGapsContains(),a==null?List.of():a.getUnresolvedRiskGaps(),ok,bad);}
void fb(TriageEvalCase c,TriageEvalCase.Expected e,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok,List<String> bad){eq(F,"nextAction",e.getNextAction(),n==null?null:n.getNextAction(),ok,bad);slots(F,"slotValues",e.getSlotValues(),n==null?null:n.getSlotValues(),ok,bad,false);slots(F,"finalSlotValues",e.getFinalSlotValues(),n==null?null:n.getSlotValues(),ok,bad,false);slots(F,"slotStatuses",e.getSlotStatuses(),n==null?null:n.getSlotValues(),ok,bad,true);exact(F,"answeredSlots",e.getAnsweredSlotsContains(),n==null?List.of():n.getAnsweredSlots(),ok,bad,true);exact(F,"pendingSlots",e.getPendingSlotsNotContains(),n==null?List.of():n.getPendingSlots(),ok,bad,false);risk(e.getRiskLevelAtLeast(),n,ok,bad);qp(e.getQuestionPlan(),n,ok,bad);ack(e.getMustAcknowledgeInsufficient(),n,ok,bad);pol(c,e.getFactPolarityHints(),n,ok,bad);hints(e.getRiskHintsContains(),n,ok);}
void eq(String l,String n,String e,String a,List<String> ok,List<String> bad){if(e==null)return;if(e.equals(a))ok.add(tag(l,n+"="+a));else bad.add(tag(l,"expected "+n+"="+e+", actual="+a));}
void eq(String l,String n,Boolean e,Boolean a,List<String> ok,List<String> bad){if(e==null)return;if(Objects.equals(e,a))ok.add(tag(l,n+"="+a));else bad.add(tag(l,"expected "+n+"="+e+", actual="+a));}
void atleast(String l,String n,Integer e,Integer a,List<String> ok,List<String> bad){if(e==null)return;if(a!=null&&a>=e)ok.add(tag(l,n+"AtLeast="+e+" actual="+a));else bad.add(tag(l,"expected "+n+"AtLeast="+e+", actual="+a));}
void slots(String l,String n,Map<String,String> e,Map<String,TriageEvalNormalizer.SlotSnapshot> a,List<String> ok,List<String> bad,boolean status){if(e==null||e.isEmpty())return;for(var en:e.entrySet()){var s=a==null?null:a.get(en.getKey());String v=s==null?null:(status?s.getStatus():s.getValue());if(en.getValue().equals(v))ok.add(tag(l,n+" contains "+en.getKey()+"="+v));else bad.add(tag(l,"expected "+n+" contains "+en.getKey()+"="+en.getValue()+", actual="+v));}}
void frag(String l,String n,List<String> e,List<String> a,List<String> ok,List<String> bad){if(e==null||e.isEmpty())return;for(String v:e)if(has(a,v))ok.add(tag(l,n+" contains "+v));else bad.add(tag(l,"expected "+n+" contains "+v+", actual="+a));}
void nfrag(String l,String n,List<String> e,List<String> a,List<String> ok,List<String> bad){if(e==null||e.isEmpty())return;for(String v:e)if(!has(a,v))ok.add(tag(l,n+" excludes "+v));else bad.add(tag(l,"expected "+n+" excludes "+v+", actual="+a));}
void exact(String l,String n,List<String> e,List<String> a,List<String> ok,List<String> bad,boolean want){if(e==null||e.isEmpty())return;for(String v:e){boolean h=a!=null&&a.contains(v);if(h==want)ok.add(tag(l,n+(want?" contains ":" excludes ")+v));else bad.add(tag(l,"expected "+n+(want?" contains ":" excludes ")+v+", actual="+a));}}
boolean has(List<String> a,String e){if(e==null||e.isBlank()||a==null)return false;String n=nm(e);for(String v:a){String x=nm(v);if(!x.isEmpty()&&(x.contains(n)||n.contains(x)))return true;}return false;}
void risk(String e,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok,List<String> bad){if(e==null)return;String a=n==null?null:n.getRiskLevel();if(rank(a)>=rank(e))ok.add(tag(F,"riskLevelAtLeast="+e+" actual="+a));else bad.add(tag(F,"expected riskLevelAtLeast="+e+", actual="+a));}
void qp(TriageEvalCase.QuestionPlanExpectation e,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok,List<String> bad){if(e==null)return;var q=n==null?null:n.getQuestionPlan();var next=q==null?List.<String>of():q.getNextSlotsToAsk();any(F,"questionPlan mustAskAnyOf",e.getMustAskAnyOf(),next,ok,bad);any(F,"questionPlan shouldAskAnyOf",e.getShouldAskAnyOf(),next,ok,bad);if(e.getMustNotAsk()!=null)for(String v:e.getMustNotAsk())if(next==null||!next.contains(v))ok.add(tag(F,"questionPlan excludes "+v));else bad.add(tag(F,"expected questionPlan excludes "+v+", actual="+next));if(e.getMaxAskCount()!=null){Integer c=q==null?null:q.getAskCount();if(c!=null&&c<=e.getMaxAskCount())ok.add(tag(F,"questionPlan askCount="+c));else bad.add(tag(F,"expected questionPlan askCount <= "+e.getMaxAskCount()+", actual="+c));}}
void any(String l,String n,List<String> e,List<String> a,List<String> ok,List<String> bad){if(e==null||e.isEmpty())return;boolean h=a!=null&&e.stream().anyMatch(a::contains);if(h)ok.add(tag(l,n+" satisfied by "+a));else bad.add(tag(l,"expected "+n+"="+e+", actual="+a));}
void ack(Boolean r,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok,List<String> bad){if(!Boolean.TRUE.equals(r))return;String x=n==null?null:n.getFinalReply();boolean h=x!=null&&(x.contains("更准确判断")||x.contains("再补充")||x.contains("请补充"));if(h)ok.add(tag(F,"finalReply acknowledges insufficient info"));else bad.add(tag(F,"expected finalReply acknowledges insufficient info, actual="+x));}
void pol(TriageEvalCase c,List<TriageEvalCase.FactPolarityHint> hs,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok,List<String> bad){if(hs==null||hs.isEmpty())return;List<Fact> fs=n==null?List.of():n.getFacts();boolean strict=c!=null&&Boolean.TRUE.equals(c.getStrictCompatibilityFacts());for(var h:hs){boolean m=fs.stream().anyMatch(f->mt(f,h));if(m)ok.add(tag(C,"factPolarityHint matched evidence="+h.getEvidence()));else if(strict)bad.add(tag(C,"expected factPolarityHint evidence="+h.getEvidence()+" polarity="+h.getPolarity()));else ok.add(tag(C,"factPolarityHint ignored evidence="+h.getEvidence()+" polarity="+h.getPolarity()));}}
void hints(List<String> hs,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok){if(hs==null||hs.isEmpty())return;String r=n==null?"":nz(n.getFinalReply());for(String h:hs)ok.add(tag(C,(rh(r,h)?"riskHintsContains observed ":"riskHintsContains missing ")+h));}
void forbidden(List<String> rs,TriageEvalNormalizer.NormalizedEvalResult n,List<String> ok,List<String> bad){if(rs==null||rs.isEmpty())return;for(String rule:rs)if(fh(rule,n))bad.add(tag(F,"forbidden matched: "+rule));else ok.add(tag(F,"forbidden not matched: "+rule));}
boolean fh(String rule,TriageEvalNormalizer.NormalizedEvalResult n){if(rule==null||n==null)return false;var s=n.getSlotValues();String r=nz(n.getFinalReply()),a=n.getNextAction();if(rule.contains("=")){String[] p=rule.split("=",2);var x=s==null?null:s.get(p[0]);return p.length==2&&x!=null&&p[1].equals(x.getValue());}List<String> sel=mg(n.getPlanner()==null?null:n.getPlanner().getSelectedGaps(),n.getQuestionPlan()==null?null:n.getQuestionPlan().getNextSlotsToAsk());if(REASK.containsKey(rule)&&REASK.get(rule).stream().anyMatch(v->has(sel,v)))return true;return switch(rule){case "REASK_FEVER_PRESENCE"->anyTxt(r,"有没有发热","是否发热");case "REASK_NAUSEA_PRESENCE"->anyTxt(r,"有没有恶心","是否恶心");case "REASK_VOMITING_PRESENCE"->anyTxt(r,"有没有吐","是否呕吐","吐过");case "REASK_DURATION"->anyTxt(r,"什么时候开始","持续多久");case "REASK_BODY_PART"->anyTxt(r,"哪个部位","哪里不舒服","哪个位置");case "GENERATE_REPORT"->"GENERATE_REPORT".equals(a);case "NO_WARNING","ROUTINE_FOLLOW_UP_FIRST","TREAT_AS_ROUTINE_SLOT_FILLING","TREAT_AS_ROUTINE_GYNE_QUERY"->"ASK_CLARIFICATION".equals(a);case "INVENT_TEMPERATURE"->s!=null&&s.containsKey("TEMPERATURE");case "INVENT_BODY_PART"->s!=null&&s.containsKey("BODY_PART");case "INVENT_DURATION"->s!=null&&s.containsKey("DURATION");case "INVENT_SEVERITY"->s!=null&&s.containsKey("PAIN_SEVERITY");case "GENERATE_NORMAL_REPORT"->"GENERATE_REPORT".equals(a)&&!anyTxt(r,"风险","警惕","及时就医");default->false;};}
boolean mt(Fact f,TriageEvalCase.FactPolarityHint h){if(f==null||h==null)return false;boolean e=h.getEvidence()==null||h.getEvidence().equals(f.getEvidence());FactPolarity p=sp(h.getPolarity());boolean m=h.getPolarity()==null||(f.getPolarity()!=null&&p==f.getPolarity());return e&&m;}
FactPolarity sp(String v){try{return v==null?null:FactPolarity.valueOf(v);}catch(Exception ex){return null;}}
boolean rh(String r,String h){return switch(h){case "ALTERED_CONSCIOUSNESS"->anyTxt(r,"意识","昏迷","不清醒");case "SEIZURE"->anyTxt(r,"抽搐","惊厥");default->false;};}
boolean anyTxt(String t,String... xs){if(t==null||t.isBlank())return false;for(String x:xs)if(x!=null&&!x.isBlank()&&t.contains(x))return true;return false;}
List<String> mg(List<String>a,List<String>b){List<String> out=new ArrayList<>();if(a!=null)out.addAll(a);if(b!=null)out.addAll(b);return out;}
String histComplaint(TriageEvalCase.HistoryExpectation e){if(e==null)return null;String v=e.getFinalPrimaryComplaint();if(v!=null&&!v.isBlank())return v;v=e.getFinalPrimarySymptomMustPersist();return v==null||v.isBlank()?null:v;}String nm(String v){return v==null?"":v.replace("-","").replace("_","").replace(" ","").toUpperCase(Locale.ROOT);}String nz(String v){return v==null?"":v;}int rank(String r){return r==null?0:switch(r){case "LOW"->1;case "MEDIUM"->2;case "HIGH"->3;default->0;};}String tag(String l,String d){return "["+l+"] "+d;}
}
